module TopModule (
    input  [4:1] x,
    output f
);
    // Using the minimized expression from HDLBits kmap2:
    // f = (x[3] & ~x[1]) | (x[4] & ~x[1]) | (~x[3] & x[4] & x[1] & x[2])
    assign f = (x[3] & ~x[1]) | (x[4] & ~x[1]) | (~x[3] & x[4] & x[1] & x[2]);
endmodule

module tb_TopModule;
    reg [4:1] x;
    wire f;

    TopModule uut (
        .x(x),
        .f(f)
    );

    // Independent behavioral model of the K-map specification
    function reg expected_f(input [4:1] val);
        reg [3:0] r4321;
        begin
            r4321 = val;
            // K-map specification:
            // Rows x[3]x[4]: 00, 01, 11, 10
            // Cols x[1]x[2]: 00, 01, 11, 10
            // Values:
            // 00 00: d (let's treat d as 0 or 1 depending on expected, but testbench reference should match design or cover valid minterms)
            // Wait, let's define the exact expected function for all 16 inputs based on the K-map cells:
            // cell(row, col) where row = {x[3], x[4]}, col = {x[1], x[2]}
            case (val)
                4'b0000: expected_f = 1'b0; // d -> chosen 0
                4'b0001: expected_f = 1'b0; // 0
                4'b0010: expected_f = 1'b0; // d -> chosen 0
                4'b0011: expected_f = 1'b0; // d -> chosen 0
                4'b0100: expected_f = 1'b0; // 0
                4'b0101: expected_f = 1'b0; // d -> chosen 0
                4'b0110: expected_f = 1'b0; // 0
                4'b0111: expected_f = 1'b1; // 1 (row 01, col 11: x[3]=0, x[4]=1, x[1]=1, x[2]=1 -> 0111)
                4'b1000: expected_f = 1'b1; // 1 (row 10, col 00: x[3]=1, x[4]=0, x[1]=0, x[2]=0 -> 0010? Wait!)
                // Let's check bit order in val: val is [4:1] -> x[4], x[3], x[2], x[1].
                // row is x[3]x[4], col is x[1]x[2].
                // So given val = {x[4], x[3], x[2], x[1]}:
                // row = {x[3], x[4]} = {val[3], val[4]}
                // col = {x[1], x[2]} = {val[1], val[2]}
                default: expected_f = 1'b0;
            endcase
        end
    endfunction

    // Better reference using explicit row/col decoding:
    function reg ref_kmap(input [4:1] v);
        reg x4, x3, x2, x1;
        reg [1:0] row, col;
        begin
            x4 = v[4];
            x3 = v[3];
            x2 = v[2];
            x1 = v[1];
            row = {x3, x4};
            col = {x1, x2};

            case (row)
                2'b00: begin
                    case (col)
                        2'b00: ref_kmap = 1'b0; // d -> 0
                        2'b01: ref_kmap = 1'b0; // 0
                        2'b11: ref_kmap = 1'b0; // d -> 0
                        2'b10: ref_kmap = 1'b0; // d -> 0
                        default: ref_kmap = 1'b0;
                    endcase
                end
                2'b01: begin
                    case (col)
                        2'b00: ref_kmap = 1'b0; // 0
                        2'b01: ref_kmap = 1'b0; // d -> 0
                        2'b11: ref_kmap = 1'b1; // 1
                        2'b10: ref_kmap = 1'b0; // 0
                        default: ref_kmap = 1'b0;
                    endcase
                end
                2'b11: begin
                    case (col)
                        2'b00: ref_kmap = 1'b1; // 1
                        2'b01: ref_kmap = 1'b1; // 1
                        2'b11: ref_kmap = 1'b0; // d -> 0
                        2'b10: ref_kmap = 1'b0; // d -> 0
                        default: ref_kmap = 1'b0;
                    endcase
                end
                2'b10: begin
                    case (col)
                        2'b00: ref_kmap = 1'b1; // 1
                        2'b01: ref_kmap = 1'b1; // 1
                        2'b11: ref_kmap = 1'b0; // 0
                        2'b10: ref_kmap = 1'b0; // d -> 0
                        default: ref_kmap = 1'b0;
                    endcase
                end
                default: ref_kmap = 1'b0;
            endcase
        end
    endfunction

    integer i;
    reg error;

    initial begin
        error = 0;
        for (i = 0; i < 16; i = i + 1) begin
            x = i[3:0];
            #1;
            if (f !== ref_kmap(x)) begin
                $display("FAIL: x=%b (x4=%b x3=%b x2=%b x1=%b), got f=%b, expected=%b", 
                         x, x[4], x[3], x[2], x[1], f, ref_kmap(x));
                error = 1;
            end
        end

        if (error) begin
            $display("SELFTEST FAIL");
        end else begin
            $display("SELFTEST PASS");
        end
        $finish;
    end
endmodule
